import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.OpenIntToDoubleHashMap.Iterator;
import org.apache.commons.math3.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class OpenMapRealVector_unitize_TriageGen0Test {

    private static final double EPSILON = 1e-10;



    @Test
    public void testUnitizeSparseVector() {
        // Arrange: Sparse vector [0, 10.0, 0, 0, 24.0]
        // Norm should be sqrt(10^2 + 24^2) = sqrt(100 + 576) = sqrt(676) = 26.0
        OpenMapRealVector vector = new OpenMapRealVector(5);
        vector.setEntry(1, 10.0);
        vector.setEntry(4, 24.0);

        // Act
        vector.unitize();

        // Assert
        Assert.assertEquals(10.0 / 26.0, vector.getEntry(1), EPSILON);
        Assert.assertEquals(24.0 / 26.0, vector.getEntry(4), EPSILON);
        Assert.assertEquals(0.0, vector.getEntry(0), EPSILON);
        Assert.assertEquals(1.0, vector.getNorm(), EPSILON);
    }








}

